/// Cases where our result and the reference differ by more than the
/// reference's bound and nothing independent has decided between them
/// yet. An entry is an OPEN question: not scored, listed in every
/// report, to be settled. (There were seven others; all were settled for
/// our result, by a direct integration or by the reference contradicting
/// itself, and are in [`REFERENCE_OFF`] with the evidence.)
///
/// `near/cylinder-torus/009` (the developer, 2026-10-13): the rim of a
/// cylinder ten tolerances inside a torus, by construction (gap -10). Ours:
/// the fuse is one shell and the common a sliver. FreeCAD: two shells and
/// nothing in common, which contradicts the construction. That shows the
/// reference is off, not that ours is right: nothing independent measures
/// our sliver, and `mass_properties` does not resolve it at this scale (it
/// reports -2.4e-10 of a body of 23; its area is 2.98e-7).
const UNDECIDED: &[&str] = &["near/cylinder-torus/009"];

/// The linear tolerance at scale 1, as in the corpus header.
const TOLERANCE: f64 = 1e-6;

const OPS: [(BooleanOp, &str, &str); 3] = [
    (BooleanOp::Union, "union", "fuse"),
    (BooleanOp::Subtract, "subtract", "cut"),
    (BooleanOp::Intersect, "intersect", "common"),
];

#[derive(Clone, Debug, PartialEq)]
enum Outcome {
    Match,
    MatchApproximate,
    Empty,
    Unsupported(String),
    Unscored,
    /// The body agrees with the reference, counted by sampled points that
    /// `boolean::contains_points` classifies; `mass_properties` of it
    /// does not (or refuses it).
    Measure(String),
    Mismatch(String),
    Invalid(String),
}

impl Outcome {
    fn agrees(&self) -> bool {
        matches!(
            self,
            Outcome::Match | Outcome::MatchApproximate | Outcome::Empty
        )
    }

    fn name(&self) -> &'static str {
        match self {
            Outcome::Match => "match",
            Outcome::MatchApproximate => "match~",
            Outcome::Empty => "empty",
            Outcome::Unsupported(_) => "unsupported",
            Outcome::Unscored => "unscored",
            Outcome::Measure(_) => "measure",
            Outcome::Mismatch(_) => "MISMATCH",
            Outcome::Invalid(_) => "INVALID",
        }
    }
}

fn number(v: &Value, path: &[&str]) -> Option<f64> {
    let mut at = v;
    for key in path {
        at = at.get(key)?;
    }
    at.as_f64()
}

fn vector(v: &Value, key: &str) -> Option<Vec3> {
    let a = v.get(key)?.as_array()?;
    Some(Vec3::new(
        a.first()?.as_f64()?,
        a.get(1)?.as_f64()?,
        a.get(2)?.as_f64()?,
    ))
}

/// The solid of the corpus, with every length times `k`.
fn build(solid: &Value, k: f64) -> Result<Body, String> {
    let get = |key: &str| {
        number(solid, &[key])
            .map(|x| x * k)
            .ok_or(format!("no {key}"))
    };
    let origin = vector(solid, "origin").ok_or("no origin")? * k;
    let z = vector(solid, "z").ok_or("no z")?;
    let x = vector(solid, "x").ok_or("no x")?;
    let frame = Frame::new(origin, z, x).ok_or("degenerate frame")?;
    let kind = solid.get("kind").and_then(Value::as_str).unwrap_or("");
    let body = match kind {
        "block" => {
            let size = vector(solid, "size").ok_or("no size")? * k;
            primitives::block(&frame, size.x, size.y, size.z)
        }
        "cylinder" => primitives::cylinder(&frame, get("radius")?, get("height")?),
        "cone" => primitives::cone(&frame, get("radius")?, get("height")?),
        "sphere" => primitives::sphere(&frame, get("radius")?),
        "torus" => primitives::torus(&frame, get("major")?, get("minor")?),
        // The schema leaves room for extrusions and revolved profiles;
        // this test does not build them yet.
        other => return Err(format!("unknown kind `{other}`")),
    };
    body.map_err(|e| e.to_string())
}

/// What a body measures, at scale 1.
#[derive(Clone, Copy, Debug)]
struct Measured {
    volume: f64,
    area: f64,
    centroid: Option<Vec3>,
    shells: usize,
}

fn measure(body: &Body, k: f64) -> Result<Measured, String> {
    let m = mass_properties(body).map_err(|e| format!("mass properties: {e}"))?;
    Ok(Measured {
        volume: m.volume / (k * k * k),
        area: m.area / (k * k),
        centroid: m.centroid.map(|c| c * (1.0 / k)),
        shells: body.shells.len(),
    })
}

/// How closely a result must agree with FreeCAD's, at scale 1. Every term
/// is the size of an error the *reference* is known or measured to have;
/// nothing is tuned to our results.
///
/// - `1e-7` of the result's own volume or area: the agreement asked of
///   exact geometry.
/// - A floor relative to the operands, `vol A + vol B` (or their areas):
///   FreeCAD integrates numerically, and its three results obey
///   `vol(A ∪ B) = vol A + vol B − vol(A ∩ B)` and
///   `vol(A − B) = vol A − vol(A ∩ B)` only to a residual the corpus
///   records per case. The floor is four times that residual, and never
///   less than 1e-9 (the limit below which the corpus calls a reference
///   `exact`). For area the residual of
///   `area(A ∪ B) + area(A ∩ B) = area A + area B` is used where that
///   identity holds (nothing coincident); elsewhere the volume residual
///   stands in for it, which is an assumption: the same integrator, the
///   same faces.
/// - Where FreeCAD's result has an approximated (spline) edge, the curve
///   itself is only within FreeCAD's tolerance `t` of the true one, and
///   ours within the document tolerance: the volume may differ by
///   `(t + tolerance) × area` and the area by `(t + tolerance) × total
///   edge length`. The identities cannot see this error: all three
///   results share the curve.
/// - A case of the `near` category is a contact that is off by a `gap`.
///   Where the gap is no more than the tolerance, the solids may be read
///   as given or as touching exactly, and the kernel may close the gap by
///   treating points on either side of it as one: its result then lies
///   between the two readings, which differ by at most `gap × area` in
///   volume and `gap × total edge length` in area. (Beyond the tolerance,
///   at ten tolerances, there is no such slack.)
/// - The centroid is a first moment over the volume: its error is at most
///   the volume bound times the size of the pair, over the volume.
struct Bounds {
    volume: f64,
    area: f64,
    /// Per unit of `1 / volume`.
    moment: f64,
}

fn bounds(case: &Value, result: &Value, size: f64, gap: f64) -> Option<Bounds> {
    let reference = case.get("freecad")?;
    let (v, a) = (number(result, &["v"])?, number(result, &["a"])?);
    let volumes = number(reference, &["a", "v"])? + number(reference, &["b", "v"])?;
    let areas = number(reference, &["a", "a"])? + number(reference, &["b", "a"])?;
    let off_volume = number(case, &["volume_residual"])?;
    let off_area = number(case, &["area_residual"])
        .unwrap_or(off_volume)
        .max(off_volume);
    let mut volume = 1e-7 * v + (4.0 * off_volume).max(1e-9) * volumes;
    let mut area = 1e-7 * a + (4.0 * off_area).max(1e-9) * areas;
    let mut slack = gap;
    if result.get("spl").and_then(Value::as_bool) == Some(true) {
        slack += number(result, &["t"])? + TOLERANCE;
    }
    if slack > 0.0 {
        volume += slack * a;
        // An empty result has no edges.
        area += slack * number(result, &["len"]).unwrap_or(0.0);
    }
    Some(Bounds {
        volume,
        area,
        moment: volume * size,
    })
}

/// `Ok` when our result agrees with FreeCAD's `result` of `case`; else
/// what differs. `ours` is `None` for an empty result. `gap` is the
/// distance within which the input may be read either way.
fn agree(
    case: &Value,
    result: &Value,
    ours: Option<&Measured>,
    size: f64,
    gap: f64,
) -> Result<(), String> {
    let bounds = bounds(case, result, size, gap).ok_or("the reference lacks a number")?;
    let (v, a) = (
        number(result, &["v"]).unwrap_or(f64::NAN),
        number(result, &["a"]).unwrap_or(f64::NAN),
    );
    let Some(ours) = ours else {
        return if v <= bounds.volume {
            Ok(())
        } else {
            Err(format!("we say empty, the reference has volume {v:e}"))
        };
    };
    let mut wrong = String::new();
    if (ours.volume - v).abs() > bounds.volume {
        let _ = write!(
            wrong,
            "volume {:e} vs {v:e} (off {:.2e}, bound {:.2e}); ",
            ours.volume,
            ours.volume - v,
            bounds.volume
        );
    }
    if (ours.area - a).abs() > bounds.area {
        let _ = write!(
            wrong,
            "area {:e} vs {a:e} (off {:.2e}, bound {:.2e}); ",
            ours.area,
            ours.area - a,
            bounds.area
        );
    }
    // A centroid means something only where there is volume to speak of.
    if v > 10.0 * bounds.volume {
        match (ours.centroid, vector(result, "c")) {
            (Some(c), Some(r)) => {
                let (off, bound) = (c.distance(r), bounds.moment / v);
                if off > bound {
                    let _ = write!(wrong, "centroid off {off:.2e} (bound {bound:.2e}); ");
                }
            }
            _ => wrong.push_str("a centroid is missing; "),
        }
    }
    let shells = result
        .get("n")
        .and_then(|n| n.get(1))
        .and_then(Value::as_u64);
    if wrong.is_empty() && shells != Some(ours.shells as u64) {
        let _ = write!(wrong, "{} shells vs {shells:?}; ", ours.shells);
    }
    if wrong.is_empty() { Ok(()) } else { Err(wrong) }
}

fn reliable(case: &Value) -> bool {
    matches!(
        case.get("reference").and_then(Value::as_str),
        Some("exact" | "approximate")
    )
}

/// Our result against the references it may agree with: the case's own
/// and, where the case is a contact that is off by no more than the
/// tolerance, that of the exact contact (`snap`): within the tolerance
/// either reading of the input is right.
fn score(
    case: &Value,
    snap: Option<&Value>,
    field: &str,
    ours: Option<&Measured>,
    size: f64,
) -> Outcome {
    let mut first_difference = None;
    let mut compared = false;
    // The gap of a case that may be read as its exact contact, at scale 1.
    let gap = match (snap, number(case, &["gap"])) {
        (Some(_), Some(tolerances)) => tolerances.abs() * TOLERANCE,
        _ => 0.0,
    };
    for candidate in [Some(case), snap].into_iter().flatten() {
        if !reliable(candidate) {
            continue;
        }
        let Some(result) = candidate.get("freecad").and_then(|f| f.get(field)) else {
            continue;
        };
        compared = true;
        match agree(candidate, result, ours, size, gap) {
            Ok(()) if ours.is_none() => return Outcome::Empty,
            Ok(()) => {
                let exact = candidate.get("reference").and_then(Value::as_str) == Some("exact");
                return if exact {
                    Outcome::Match
                } else {
                    Outcome::MatchApproximate
                };
            }
            Err(difference) => {
                first_difference.get_or_insert(difference);
            }
        }
    }
    // With only the snapped reference to go by, a difference proves
    // nothing: the exact answer of the case itself is unknown.
    if !compared || !reliable(case) {
        return Outcome::Unscored;
    }
    Outcome::Mismatch(first_difference.unwrap_or_default())
}

/// The volume of `body` at scale 1 by counting sampled points that the
/// kernel's own point classification puts inside it, and five standard
/// deviations of that count. Seeded: the same points every run.
fn sampled_volume(body: &Body, k: f64, tolerance: &Tolerance) -> Option<(f64, f64)> {
    const SAMPLES: usize = 20_000;
    let (lo, hi) = body.bbox().ok()?.corners()?;
    let mut state = 0x9E37_79B9_7F4A_7C15_u64;
    let mut unit = || {
        state = state
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        (state >> 11) as f64 / (1u64 << 53) as f64
    };
    let points: Vec<Vec3> = (0..SAMPLES)
        .map(|_| {
            Vec3::new(
                lo.x + (hi.x - lo.x) * unit(),
                lo.y + (hi.y - lo.y) * unit(),
                lo.z + (hi.z - lo.z) * unit(),
            )
        })
        .collect();
    let found = contains_points(body, &points, tolerance).ok()?;
    let decided = found.iter().flatten().count();
    let inside = found.iter().flatten().filter(|&&x| x).count();
    if decided * 10 < SAMPLES * 9 {
        return None;
    }
    let cell = (hi.x - lo.x) * (hi.y - lo.y) * (hi.z - lo.z) / (k * k * k);
    let fraction = inside as f64 / decided as f64;
    let deviation = (fraction * (1.0 - fraction) / decided as f64).sqrt();
    Some((
        cell * fraction,
        cell * (5.0 * deviation + 5.0 / decided as f64),
    ))
}

/// A mismatch between the reference and what `mass_properties` says of
/// our body is no mismatch of the body when its volume, measured without
/// `mass_properties`, agrees with the reference and not with that.
fn second_opinion(
    case: &Value,
    field: &str,
    body: &Body,
    measured: Option<&Measured>,
    k: f64,
    tolerance: &Tolerance,
    difference: &str,
) -> Option<Outcome> {
    let reference = number(case, &["freecad", field, "v"])?;
    let (sampled, slack) = sampled_volume(body, k, tolerance)?;
    let agrees = (sampled - reference).abs() <= slack;
    // Where the two differ by less than sampling resolves, sampling
    // cannot say which is right: that stays a mismatch.
    let resolved = measured.is_none_or(|m| (m.volume - reference).abs() > 2.0 * slack);
    (agrees && resolved).then(|| {
        Outcome::Measure(format!(
            "sampled volume {sampled:.6e} ± {slack:.1e} agrees with the reference {reference:.6e}; \
             mass_properties: {difference}"
        ))
    })
}

/// The sum of a hash of every result of the run: the body with all its
/// numbers and where everything came from. Two builds of the kernel that
/// print the same sum gave the same results, bit for bit (it is how a
/// change that should only make the kernel faster is checked).
static DIGEST: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

fn digest(result: &craft3d_kernel::boolean::BooleanResult) {
    use std::hash::{Hash, Hasher};
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    format!("{result:?}").hash(&mut hasher);
    DIGEST.fetch_add(hasher.finish(), std::sync::atomic::Ordering::Relaxed);
}

/// The three outcomes of a case, in the order of [`OPS`].
fn run_case(case: &Value, snap: Option<&Value>, verbose: bool) -> Vec<Outcome> {
    let k = number(case, &["scale"]).unwrap_or(1.0);
    let all = |outcome: Outcome| vec![outcome; OPS.len()];
    let (a, b) = match (
        case.get("a").map(|s| build(s, k)),
        case.get("b").map(|s| build(s, k)),
    ) {
        (Some(Ok(a)), Some(Ok(b))) => (a, b),
        other => {
            return all(Outcome::Invalid(format!(
                "cannot build the operands: {other:?}"
            )));
        }
    };
    let size = {
        let mut both = Bbox3::EMPTY;
        for body in [&a, &b] {
            match body.bbox().ok().and_then(|bbox| bbox.corners()) {
                Some((lo, hi)) => {
                    both.add(lo);
                    both.add(hi);
                }
                None => return all(Outcome::Invalid("an operand has no box".to_string())),
            }
        }
        both.diagonal() / k
    };
    // The mapping is only trusted when both kernels built the same
    // operands: primitives, whose volume, area and centroid both sides
    // know to rounding.
    if let Some(reference) = case.get("freecad") {
        for (name, body) in [("a", &a), ("b", &b)] {
            let ours = match measure(body, k) {
                Ok(ours) => ours,
                Err(e) => return all(Outcome::Invalid(format!("operand {name}: {e}"))),
            };
            let (Some(v), Some(area), Some(c)) = (
                number(reference, &[name, "v"]),
                number(reference, &[name, "a"]),
                reference.get(name).and_then(|r| vector(r, "c")),
            ) else {
                continue;
            };
            let off = ours.centroid.map_or(f64::INFINITY, |o| o.distance(c));
            if (ours.volume - v).abs() > 1e-9 * v
                || (ours.area - area).abs() > 1e-9 * area
                || off > 1e-9 * size
            {
                return all(Outcome::Invalid(format!(
                    "operand {name} differs from FreeCAD's: volume {:e} vs {v:e}, \
                     area {:e} vs {area:e}, centroid off {off:.2e}",
                    ours.volume, ours.area
                )));
            }
        }
    }
    let tolerance = Tolerance::new(TOLERANCE * k, 1e-9).unwrap();
    let mut outcomes = Vec::new();
    for (op, name, field) in OPS {
        let result = catch_unwind(AssertUnwindSafe(|| boolean(&a, &b, op, &tolerance)));
        let mut ours = None;
        let outcome = match result {
            Err(_) => Outcome::Invalid("panic".to_string()),
            Ok(Err(KernelError::Unsupported { reason, .. })) => {
                Outcome::Unsupported(reason.to_string())
            }
            Ok(Err(KernelError::EmptyResult { .. })) => score(case, snap, field, None, size),
            Ok(Err(other)) => Outcome::Invalid(format!("error: {other}")),
            Ok(Ok(result)) => {
                digest(&result);
                let defects = check(&result.body, &tolerance);
                match measure(&result.body, k) {
                    _ if !defects.is_empty() => {
                        Outcome::Invalid(format!("fails the checker: {:?}", defects.first()))
                    }
                    Err(e) => second_opinion(case, field, &result.body, None, k, &tolerance, &e)
                        .unwrap_or(Outcome::Invalid(e)),
                    Ok(measured) => {
                        ours = Some(measured);
                        match score(case, snap, field, Some(&measured), size) {
                            Outcome::Mismatch(difference) => second_opinion(
                                case,
                                field,
                                &result.body,
                                Some(&measured),
                                k,
                                &tolerance,
                                &difference,
                            )
                            .unwrap_or(Outcome::Mismatch(difference)),
                            other => other,
                        }
                    }
                }
            }
        };
        let id = case.get("id").and_then(Value::as_str).unwrap_or("?");
        let outcome = match outcome {
            Outcome::Mismatch(_)
                if REFERENCE_OFF.iter().any(|(case, _)| *case == id) || UNDECIDED.contains(&id) =>
            {
                Outcome::Unscored
            }
            other => other,
        };
        if verbose {
            println!("{id} {name}: {outcome:?}");
            println!("    ours      {ours:?}");
            println!(
                "    reference {}",
                case.get("freecad")
                    .and_then(|f| f.get(field))
                    .map_or("none".to_string(), Value::to_string)
            );
        }
        outcomes.push(outcome);
    }
    outcomes
}

fn corpus() -> Value {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/boolean_corpus.json");
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("{} is not JSON: {e}", path.display()))
}

/// Counts of one row of the table.
#[derive(Default, Clone)]
struct Row {
    counts: BTreeMap<&'static str, usize>,
    reasons: BTreeMap<String, usize>,
}

impl Row {
    fn add(&mut self, outcome: &Outcome) {
        *self.counts.entry(outcome.name()).or_default() += 1;
        if let Outcome::Unsupported(reason) = outcome {
            *self.reasons.entry(reason.clone()).or_default() += 1;
        }
    }

    fn count(&self, name: &str) -> usize {
        self.counts.get(name).copied().unwrap_or(0)
    }
}

const COLUMNS: [&str; 8] = [
    "match",
    "match~",
    "empty",
    "unsupported",
    "unscored",
    "measure",
    "MISMATCH",
    "INVALID",
];

fn table(rows: &BTreeMap<(String, String), Row>, categories: &[String]) -> String {
    // A letter per reason, in order of first appearance by row.
    let mut letters: BTreeMap<String, char> = BTreeMap::new();
    let mut legend = Vec::new();
    for row in rows.values() {
        for reason in row.reasons.keys() {
            if !letters.contains_key(reason) {
                let letter = (b'a' + (letters.len() % 26) as u8) as char;
                letters.insert(reason.clone(), letter);
                legend.push((letter, reason.clone()));
            }
        }
    }
    let line = |label: &str, row: &Row| {
        let mut text = format!("{label:<28}");
        let total: usize = row.counts.values().sum();
        let _ = write!(text, "{total:>6}");
        for column in COLUMNS {
            let _ = write!(text, "{:>12}", row.count(column));
        }
        let mut reasons: Vec<(char, usize)> = row
            .reasons
            .iter()
            .filter_map(|(reason, n)| letters.get(reason).map(|l| (*l, *n)))
            .collect();
        reasons.sort_unstable();
        text.push_str("   ");
        for (letter, n) in reasons {
            let _ = write!(text, " {letter}:{n}");
        }
        text.push('\n');
        text
    };
    let mut out = String::new();
    let mut header = format!("{:<28}{:>6}", "category / pair", "ops");
    for column in COLUMNS {
        let _ = write!(header, "{column:>12}");
    }
    header.push_str("    unsupported by reason\n");
    let mut grand = Row::default();
    let merge = |into: &mut Row, row: &Row| {
        for (name, n) in &row.counts {
            *into.counts.entry(name).or_default() += n;
        }
        for (reason, n) in &row.reasons {
            *into.reasons.entry(reason.clone()).or_default() += n;
        }
    };
    let mut summary = String::new();
    for category in categories {
        out.push_str(&header);
        let mut sum = Row::default();
        for ((c, pair), row) in rows {
            if c == category {
                out.push_str(&line(&format!("  {pair}"), row));
                merge(&mut sum, row);
            }
        }
        out.push_str(&line(&format!("{category} (all pairs)"), &sum));
        out.push('\n');
        summary.push_str(&line(category, &sum));
        merge(&mut grand, &sum);
    }
    out.push_str("Per category\n");
    out.push_str(&header);
    out.push_str(&summary);
    out.push_str(&line("TOTAL", &grand));
    out.push_str("\nPer kind pair, all categories\n");
    out.push_str(&header);
    let mut pairs: BTreeMap<&str, Row> = BTreeMap::new();
    for ((_, pair), row) in rows {
        merge(pairs.entry(pair.as_str()).or_default(), row);
    }
    for (pair, row) in &pairs {
        out.push_str(&line(pair, row));
    }
    out.push_str("\nReasons the kernel gave for refusing\n");
    for (letter, reason) in legend {
        let n = grand.reasons.get(&reason).copied().unwrap_or(0);
        let _ = writeln!(out, "  {letter}: {reason} ({n})");
    }
    out
}

#[test]
fn the_kernel_agrees_with_the_reference_kernel() {
    let started = std::time::Instant::now();
    let corpus = corpus();
    let header = &corpus["header"];
    let cases = corpus["cases"].as_array().expect("cases");
    assert_eq!(header["tolerance"].as_f64(), Some(TOLERANCE));
    let by_id: BTreeMap<&str, &Value> = cases
        .iter()
        .filter_map(|c| Some((c.get("id")?.as_str()?, c)))
        .collect();
    assert_eq!(by_id.len(), cases.len(), "case ids are unique");

    let only_case = std::env::var("BOOLEAN_CORPUS_CASE").ok();
    let only_category = std::env::var("BOOLEAN_CORPUS_CATEGORY").ok();
    let filtered = only_case.is_some() || only_category.is_some();
    let selected: Vec<&Value> = cases
        .iter()
        .filter(|c| {
            let id = c["id"].as_str().unwrap_or("");
            only_case
                .as_ref()
                .is_none_or(|part| id.contains(part.as_str()))
                && only_category
                    .as_ref()
                    .is_none_or(|category| c["category"].as_str() == Some(category.as_str()))
        })
        .collect();
    assert!(!selected.is_empty(), "the filter selects no case");
    let verbose = only_case.is_some() || std::env::var_os("BOOLEAN_CORPUS_VERBOSE").is_some();

    // In parallel, merged in the order of the file.
    let workers = std::thread::available_parallelism().map_or(4, usize::from);
    let chunk = selected.len().div_ceil(workers).max(1);
    let outcomes: Vec<Vec<Outcome>> = std::thread::scope(|scope| {
        let handles: Vec<_> = selected
            .chunks(chunk)
            .map(|part| {
                let by_id = &by_id;
                scope.spawn(move || {
                    part.iter()
                        .map(|case| {
                            let snap = case
                                .get("snap")
                                .and_then(Value::as_str)
                                .and_then(|id| by_id.get(id).copied());
                            run_case(case, snap, verbose)
                        })
                        .collect::<Vec<_>>()
                })
            })
            .collect();
        handles
            .into_iter()
            .flat_map(|h| h.join().expect("a worker panicked outside a boolean"))
            .collect()
    });

    let mut rows: BTreeMap<(String, String), Row> = BTreeMap::new();
    let mut categories: Vec<String> = Vec::new();
    let mut failures = Vec::new();
    let mut measures = Vec::new();
    let mut known = Vec::new();
    let mut healed = Vec::new();
    let mut unreliable = 0;
    for (case, outcomes) in selected.iter().zip(&outcomes) {
        let id = case["id"].as_str().unwrap_or("?");
        let category = case["category"].as_str().unwrap_or("?").to_string();
        let pair = case["pair"].as_str().unwrap_or("?").to_string();
        if !categories.contains(&category) {
            categories.push(category.clone());
        }
        unreliable += usize::from(!reliable(case));
        let row = rows.entry((category, pair)).or_default();
        for ((_, name, _), outcome) in OPS.iter().zip(outcomes) {
            row.add(outcome);
            let listed = KNOWN_MISMATCHES
                .iter()
                .find(|(known_id, op, _)| *known_id == id && op == name);
            match (outcome, listed) {
                (Outcome::Mismatch(what), Some((_, _, why))) => {
                    known.push(format!("{id} {name}: {what}[known: {why}]"));
                }
                (Outcome::Mismatch(what) | Outcome::Invalid(what), _) => {
                    failures.push(format!("{} {id} {name}: {what}", outcome.name()));
                }
                (Outcome::Measure(what), _) => measures.push(format!("{id} {name}: {what}")),
                (outcome, Some(_)) if outcome.agrees() => healed.push(format!("{id} {name}")),
                _ => {}
            }
        }
    }
    let agreeing: usize = rows
        .values()
        .map(|r| r.count("match") + r.count("match~") + r.count("empty"))
        .sum();

    let mut report = format!(
        "Boolean corpus score: our kernel against {}\n\
         corpus of {} (seed {}), {} cases selected, {} of them with an unreliable reference\n\
         one outcome per case and operation (union, subtract, intersect)\n\n",
        header["freecad"].as_str().unwrap_or("?"),
        header["date"].as_str().unwrap_or("?"),
        header["seed"],
        selected.len(),
        unreliable,
    );
    report.push_str(&table(&rows, &categories));
    let _ = writeln!(
        report,
        "\nagreeing (match + match~ + empty): {agreeing}; floor {AGREEING_FLOOR}"
    );
    println!(
        "digest of all results: {:016x}",
        DIGEST.load(std::sync::atomic::Ordering::Relaxed)
    );
    if !known.is_empty() {
        let _ = writeln!(report, "\nKnown mismatches (allow-listed):");
        for line in &known {
            let _ = writeln!(report, "  {line}");
        }
    }
    if !measures.is_empty() {
        let _ = writeln!(
            report,
            "\nBodies that agree with the reference by sampled points, while mass_properties \
             of them does not (a defect of the measurement, not of the boolean):"
        );
        for line in &measures {
            let _ = writeln!(report, "  {line}");
        }
    }
    if !failures.is_empty() {
        let _ = writeln!(report, "\nFailures:");
        for line in &failures {
            let _ = writeln!(report, "  {line}");
        }
    }
    let _ = writeln!(report, "\ntook {:.1} s", started.elapsed().as_secs_f64());
    println!("{report}");
    if !filtered {
        let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../target/evidence/booleans");
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("corpus-score.txt"), &report).unwrap();
    }

    assert!(
        failures.is_empty(),
        "{} outcomes are wrong; rerun one with BOOLEAN_CORPUS_CASE=<id> and --nocapture:\n{}",
        failures.len(),
        failures.join("\n")
    );
    assert!(
        healed.is_empty(),
        "these now agree with the reference: remove them from KNOWN_MISMATCHES:\n{}",
        healed.join("\n")
    );
    if !filtered {
        assert!(
            agreeing >= AGREEING_FLOOR,
            "{agreeing} outcomes agree with the reference, fewer than the floor of \
             {AGREEING_FLOOR}: booleans that used to be right are now refused or wrong"
        );
        if agreeing > AGREEING_FLOOR {
            println!("{agreeing} outcomes agree: raise AGREEING_FLOOR from {AGREEING_FLOOR}");
        }
    }
}

/// The corpus is what its header says: every kind pair in every category
/// where it makes sense, at three scales, and no case without a verdict on
/// its reference.
#[test]
fn the_corpus_covers_what_it_claims() {
    let corpus = corpus();
    let cases = corpus["cases"].as_array().expect("cases");
    assert_eq!(corpus["header"]["cases"].as_u64(), Some(cases.len() as u64));
    let mut per: BTreeMap<&str, BTreeMap<&str, usize>> = BTreeMap::new();
    let mut scales: BTreeMap<String, usize> = BTreeMap::new();
    let mut gaps: BTreeMap<String, usize> = BTreeMap::new();
    for case in cases {
        let category = case["category"].as_str().expect("category");
        *per.entry(category)
            .or_default()
            .entry(case["pair"].as_str().expect("pair"))
            .or_default() += 1;
        *scales
            .entry(format!("{:e}", case["scale"].as_f64().expect("scale")))
            .or_default() += 1;
        if let Some(gap) = case.get("gap").and_then(Value::as_f64) {
            *gaps.entry(format!("{gap}")).or_default() += 1;
        }
        let verdict = case["reference"].as_str().expect("reference");
        match verdict {
            "exact" | "approximate" => {
                assert!(case.get("freecad").is_some(), "{}", case["id"]);
                assert!(case.get("volume_residual").is_some(), "{}", case["id"]);
            }
            "unreliable" => assert!(case.get("why").is_some(), "{}", case["id"]),
            other => panic!("{}: unknown verdict {other}", case["id"]),
        }
        if let Some(snap) = case.get("snap").and_then(Value::as_str) {
            assert!(
                cases.iter().any(|c| c["id"].as_str() == Some(snap)),
                "{} snaps to a case that does not exist",
                case["id"]
            );
        }
    }
    // Every category has at least two hundred cases at three scales.
    assert_eq!(scales.len(), 3, "{scales:?}");
    for (category, pairs) in &per {
        let total: usize = pairs.values().sum();
        assert!(total >= 180, "{category} has only {total} cases");
    }
    // All fifteen pairs wherever any two solids can be put that way.
    for category in ["general", "parallel", "coaxial", "inside", "apart", "near"] {
        assert_eq!(per[category].len(), 15, "{category}");
    }
    // A flush face needs two planar faces, or the same solid twice.
    assert_eq!(per["flush"].len(), 8, "{:?}", per["flush"]);
    // Tangent contact needs a curved face: every pair but two blocks.
    assert_eq!(per["tangent"].len(), 14, "{:?}", per["tangent"]);
    // Contact at an edge or a vertex needs one: not spheres and tori alone.
    assert_eq!(per["contact"].len(), 12, "{:?}", per["contact"]);
    assert_eq!(gaps.len(), 7, "{gaps:?}");
}
